import fs from 'node:fs';
import path from 'node:path';
import {spawn} from 'node:child_process';
import {pathToFileURL} from 'node:url';
const run=path.dirname(new URL(import.meta.url).pathname);
const output=path.join(run,'stage/memo-os/week-9/storyboards');
const profile=fs.mkdtempSync(path.join(run,'browser-test-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--disable-gpu','--no-first-run','--no-default-browser-check','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
const pause=ms=>new Promise(r=>setTimeout(r,ms));
let ws;const pending=new Map();let serial=0;
const checks=[];const errors=[];
try{
 const active=path.join(profile,'DevToolsActivePort');
 for(let i=0;i<100&&!fs.existsSync(active);i++)await pause(100);
 if(!fs.existsSync(active))throw Error('Chrome debugging endpoint did not start');
 const port=fs.readFileSync(active,'utf8').split('\n')[0];
 const targets=await (await fetch('http://127.0.0.1:'+port+'/json')).json();
 ws=new WebSocket(targets.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
 ws.onmessage=e=>{const j=JSON.parse(e.data);if(j.id){const p=pending.get(j.id);pending.delete(j.id);if(j.error)p.reject(Error(JSON.stringify(j.error)));else p.resolve(j.result)}else if(j.method==='Runtime.exceptionThrown')errors.push(j.params)};
 function cdp(method,params={}){const id=++serial;return new Promise((resolve,reject)=>{pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}))})}
 async function evaluate(expression){const r=await cdp('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value}
 async function check(name,expression){const v=await evaluate(expression);if(!v)throw Error(name+' failed');checks.push({name,passed:true})}
 await cdp('Page.enable');await cdp('Runtime.enable');
 await cdp('Emulation.setDeviceMetricsOverride',{width:760,height:1300,deviceScaleFactor:1,mobile:false});
 await cdp('Page.navigate',{url:pathToFileURL(path.join(output,'W09_GOTW_PAGE_TURN_REHEARSAL_V1.html')).href});
 for(let i=0;i<50;i++){if(await evaluate("document.readyState==='complete' && typeof show==='function'"))break;await pause(100)}
 await evaluate('document.fonts.ready');
 await check('starts_P04_no_result',"document.querySelector('.sheet:not([hidden])').dataset.page==='P04' && actualResult===null && branch===null");
 await evaluate("document.getElementById('next').click()");
 await check('P05_uses_three_expected_drawn_frames',"document.querySelector('.sheet:not([hidden])').dataset.page==='P05' && Array.from(document.querySelectorAll('.sheet:not([hidden]) [data-source-frame]')).map(x=>x.dataset.sourceFrame).join(',')==='frame-3,frame-4,frame-5'");
 const desktop=await cdp('Page.captureScreenshot',{format:'png'});fs.writeFileSync(path.join(output,'W09_GOTW_PAGE_TURN_P05_DESKTOP.png'),Buffer.from(desktop.data,'base64'));
 await evaluate("document.getElementById('captions').click()");
 await check('caption_toggle_really_hides_caption',"getComputedStyle(document.querySelector('.sheet:not([hidden]) figcaption')).visibility==='hidden'");
 await evaluate("document.getElementById('captions').click();document.getElementById('next').click();document.getElementById('next').click()");
 await check('finale_defaults_unselected',"branch===null && actualResult===null && !document.getElementById('choose-ending').hidden && document.getElementById('stage').hidden");
 await evaluate("document.querySelector('[data-branch=A]').click()");
 await check('A_is_only_a_preview',"document.querySelector('.sheet:not([hidden])').dataset.page==='P07A' && actualResult===null");
 await evaluate("document.getElementById('clear-branch').click();document.querySelector('[data-branch=B]').click()");
 await check('B_excludes_A',"document.querySelector('.sheet:not([hidden])').dataset.page==='P07B' && document.querySelector('[data-page=P07A]').hidden && actualResult===null");
 await evaluate("document.getElementById('back').click();document.getElementById('back').click()");
 await cdp('Emulation.setDeviceMetricsOverride',{width:390,height:1100,deviceScaleFactor:1,mobile:true});await evaluate('resize()');await pause(100);
 console.log('PHONE_GEOMETRY',await evaluate("JSON.stringify({inner:innerWidth,scroll:document.documentElement.scrollWidth,oversized:Array.from(document.body.querySelectorAll('*')).filter(x=>{const b=x.getBoundingClientRect();return b.width>0&&b.right>395&&!x.closest('svg')&&!x.closest('.sheet')}).map(x=>({tag:x.tagName,cls:x.className,right:x.getBoundingClientRect().right,scroll:x.scrollWidth})).slice(0,10)})"));
 await check('phone_no_horizontal_document_overflow','document.documentElement.scrollWidth<=390');
 await check('all_P05_panels_fit_sheet',"(()=>{const p=document.querySelector('.sheet:not([hidden])'),b=p.getBoundingClientRect();return Array.from(p.querySelectorAll('figure,footer')).every(x=>x.getBoundingClientRect().bottom<=b.bottom+1)})()");
 const phone=await cdp('Page.captureScreenshot',{format:'png'});fs.writeFileSync(path.join(output,'W09_GOTW_PAGE_TURN_P05_PHONE.png'),Buffer.from(phone.data,'base64'));
 if(errors.length)throw Error('Browser exceptions: '+JSON.stringify(errors));
 fs.writeFileSync(path.join(run,'browser-checks.json'),JSON.stringify({state:'BROWSER_FUNCTIONAL_CHECKS_PASS_NOT_AUDIENCE_OR_ART_ACCEPTANCE',checks,viewport_tests:[[760,1300],[390,1100]],browser_errors:errors,original_drawing_reused:true,actual_result_selected:false,new_character_art:false},null,2)+'\n');
 console.log(JSON.stringify({checks:checks.length,passed:true,screenshots:2,actual_result_selected:false}));
}finally{if(ws)ws.close();chrome.kill('SIGTERM')}
